interface Calc {
    default int calc(int x) {
        return helper(x);
    }
    private int helper(int x) {
        return x * 2;
    }
}
class Base implements Calc {
    static int seed = 1;
    public int calc(int x) {
        return x + seed;
    }
}
class Sub extends Base {
    static int seed = 10;
    @Override public int calc(int x) {
        return super.calc(x) + seed;
    }
}
public class Main {
    public static void main(String[] args) {
        Calc c = new Sub();
        var n = c.calc(2);
        System.out.println(n);
    }
}
